package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;import java.util.*;
/** Approved appearance / actual survivor / role composition, followed by a real spawn confirmation. */
final class SurvivorCreationView extends View {
 interface Host{void create(String appearance,String faction,String profession);String status();String legacyProfession();JSONObject definition(String profession);JSONObject previewCharacter();String spawnTown(String faction);void back();}
 final Host host;final MenuFrame f=new MenuFrame();final MenuArt art;final ScenePainter survivor=new ScenePainter();int sex,body,role,faction,step;float downX,downY;boolean pressed;long changedStep;
 SurvivorCreationView(Context c,Host h){super(c);host=h;art=MenuArt.get(c);setContentDescription("Create survivor. Appearance on the left, live preview in the middle, supported roles on the right. Continue reviews your spawn before creation.");}
 String appearance(){return(sex==1?"female-":"male-")+(body==1?"2":"1");}
 String allegiance(){return faction==0?"survivor":"bandit";}
 String profession(){return host.legacyProfession().isEmpty()?(role==0?"farmer":"hunter"):host.legacyProfession();}
 JSONObject definition(){JSONObject d=host.definition(profession());return d==null?new JSONObject():d;}
 JSONObject preview(){JSONObject saved=host.previewCharacter();try{JSONObject gear=saved==null?new JSONObject():new JSONObject(saved.toString()),d=definition();gear.put("appearance",appearance());if(saved==null){gear.put("inventory",d.optJSONObject("items")==null?new JSONObject():d.optJSONObject("items")).put("equippedWeapon",d.optString("weapon","unarmed")).put("equippedArmour",d.optString("armour")).put("equippedShield",d.optBoolean("shield"));}return gear;}catch(JSONException e){return new JSONObject();}}
 void back(){if(step>0){step=0;invalidate();}else host.back();}
 protected void onDraw(Canvas c){f.begin(c,this);f.brand(c);f.text(c,step==0?"CREATE YOUR CHARACTER":"CONFIRM YOUR CHARACTER",350,46,24,580);f.panel(c,24,77,218,366,false);f.text(c,step==0?"APPEARANCE":"YOUR CHOICES",39,106,19,188);String[][] labels={{"MALE","FEMALE"},{"LEAN","STURDY"},{"SURVIVOR","BANDIT"}};String[] headings={"GENDER","BODY STYLE","ALLEGIANCE"};for(int row=0;row<3;row++){float y=142+row*100;f.text(c,headings[row],40,y-12,13,186);int chosen=row==0?sex:row==1?body:faction;if(step==1){f.text(c,labels[row][chosen],40,y+34,22,184);}else for(int i=0;i<2;i++){float x=38+i*97;f.panel(c,x,y,91,56,i==chosen);f.text(c,labels[row][i],x+8,y+33,15,75);}}
 f.text(c,"YOUR SURVIVOR",336,108,19,250);JSONObject gear=preview(),d=definition();c.save();c.clipRect(270,122,588,431);c.translate(420,426);c.scale(3.85f,3.85f);survivor.actor(c,"you:"+gear.optString("equippedWeapon","unarmed"),0,0,0xff66776a,0,false,-1,false,0,gear);c.restore();JSONObject pet=d.optJSONObject("companion");if(pet!=null){c.save();c.clipRect(270,122,588,431);c.translate(534,422);c.scale(1.35f,1.35f);survivor.companion(c,pet,0,-1);c.restore();}
 f.panel(c,616,77,320,366,false);boolean legacy=!host.legacyProfession().isEmpty();if(step==0){f.text(c,"CHOOSE YOUR ROLE",634,108,19,282);for(int i=0;i<(legacy?1:2);i++){String id=legacy?profession():i==0?"farmer":"hunter";JSONObject option=host.definition(id);float y=127+i*90;f.panel(c,632,y,288,80,legacy||role==i);if(!legacy)art.role(c,i,new RectF(638,y+5,695,y+75));f.text(c,id.toUpperCase(),705,y+26,19,204);f.wrap(c,legacy?"Your existing role and progress are retained.":option==null?"Permanent profession":option.optString("description"),705,y+49,204,2);}f.text(c,legacy?"EXISTING GEAR RETAINED":"STARTING ITEMS",634,326,15,281);JSONObject kit=d.optJSONObject("items");int i=0;if(!legacy&&kit!=null){Iterator<String> keys=kit.keys();while(keys.hasNext()&&i<8){String id=keys.next();float x=637+i%4*70,y=339+i/4*47;art.item(c,id,x,y,30);f.text(c,"×"+kit.optInt(id),x+32,y+23,12,35);i++;}}if(pet!=null)f.text(c,"Companion: "+pet.optString("name",pet.optString("kind")),634,435,13,281);}
 else{f.text(c,"ENTER THE REALM",634,108,19,282);f.text(c,"ROLE",634,145,13,281);f.text(c,profession().toUpperCase(),634,172,23,281);f.text(c,"SPAWN TOWN",634,213,13,281);f.text(c,host.spawnTown(allegiance()),634,242,22,281);f.wrap(c,"Your allegiance determines your protected starting town. Your profession persists through death.",634,281,281,4);if(pet!=null)f.text(c,"Companion: "+pet.optString("name",pet.optString("kind")),634,391,15,281);}
 f.panel(c,24,466,187,48,false);f.text(c,"< BACK",49,498,18,143);f.panel(c,616,466,320,48,true);f.text(c,step==0?"CONTINUE":"CREATE & ENTER",657,498,21,260);f.text(c,host.status(),227,496,12,370);c.restore();}
 public boolean performClick(){super.performClick();return true;}
 public boolean onTouchEvent(MotionEvent e){float x=f.x(e.getX()),y=f.y(e.getY());int type=e.getActionMasked();if(type==MotionEvent.ACTION_DOWN){pressed=true;downX=x;downY=y;return true;}if(type==MotionEvent.ACTION_CANCEL||type==MotionEvent.ACTION_POINTER_DOWN){pressed=false;return true;}if(type!=MotionEvent.ACTION_UP||!pressed)return true;pressed=false;if(Math.hypot(x-downX,y-downY)>14)return true;performClick();if(step==0){if(x>=38&&x<=226)for(int row=0;row<3;row++){float top=142+row*100;if(y>=top&&y<=top+56){int choice=x>=135?1:0;if(row==0)sex=choice;else if(row==1)body=choice;else faction=choice;}}if(host.legacyProfession().isEmpty()&&x>=632&&x<=920&&y>=127&&y<=297&&(y-127)%90<=80)role=(int)((y-127)/90);}if(y>=466&&y<=514){if(x>=24&&x<=211)back();else if(x>=616&&x<=936){if(step==0){step=1;changedStep=e.getEventTime();}else if(e.getEventTime()-changedStep>=250)host.create(appearance(),allegiance(),profession());}}invalidate();return true;}
}

